public class OrderCreatedHandler : IBackgroundService
{
    private readonly IDatabase _redis;
    private readonly IOrderRepository _orders;

    public async Task ProcessAsync(Message envelope, CancellationToken ct)
    {
        var key = $"dedup:{envelope.MessageId}";
        var exists = await _redis.KeyExistsAsync(key);
        if (exists)
        {
            _logger.LogInformation("Duplicate message {Id} skipped",
                envelope.MessageId);
            return;
        }

        var order = MapToOrder(envelope);
        await _orders.CreateAsync(order, ct);
        await _redis.StringSetAsync(key, "1", TimeSpan.FromHours(24));
    }
}
